#!/usr/bin/env bun
/**
 * Embed the icons in assets/ into src/icon-data.ts (base64), so both the
 * Bun servers and the Cloudflare Worker can serve them without file access.
 *
 *   bun run scripts/embed-icons.ts
 *
 * Re-run after replacing any file in assets/.
 */
import { resolve } from "node:path";

const root = resolve(import.meta.dir, "..");
const files = {
  ICON_512_PNG: "assets/icon-512.png",
  ICON_128_PNG: "assets/icon-128.png",
  FAVICON_ICO: "assets/favicon.ico",
};

const lines = [
  "// Generated by scripts/embed-icons.ts from assets/ — do not edit by hand.",
  "// Gnucoop logo symbol, on white for legibility in light and dark themes.",
  "",
];
for (const [name, path] of Object.entries(files)) {
  const bytes = new Uint8Array(await Bun.file(resolve(root, path)).arrayBuffer());
  lines.push(`export const ${name}_BASE64 =\n  "${Buffer.from(bytes).toString("base64")}";`, "");
}
await Bun.write(resolve(root, "src/icon-data.ts"), lines.join("\n"));
console.error(`Wrote src/icon-data.ts (${Object.keys(files).length} icons).`);
